<div class="dashboard-page-head"><div><p class="eyebrow">Portfolio</p><h1>Investments</h1><p class="muted">Review active and historical investment positions from your account.</p></div><a class="button button-secondary" href="<?= e(route('companies.index')) ?>">Explore opportunities</a></div><?php if(!$investments): ?><section class="empty-state"><h2>No investments yet</h2><p>Explore the investment opportunities currently available to your account.</p><a class="button" href="<?= e(route('companies.index')) ?>">Explore investments</a></section><?php else: ?><div class="dashboard-position-grid"><?php foreach($investments as $i): ?><article class="card position-card"><span class="badge"><?= e($i['status']) ?></span><h2><?= e($i['company_name_snapshot']) ?></h2><p class="position-ref"><?= e($i['public_id']) ?></p><div class="position-values"><div><span>Principal</span><strong><?= money((int)$i['principal_amount_minor']) ?></strong></div><div><span>Projected profit</span><strong><?= money((int)$i['projected_profit_amount_minor']) ?></strong></div></div><a class="button button-secondary" href="<?= e(route('dashboard.investments.show',['investment'=>$i['public_id']])) ?>">View investment</a></article><?php endforeach; ?></div><?php endif; ?>
